// Cspell:ignore frobenius

'use strict';

// MODULES //

var resolveTriangle = require( '@stdlib/blas/base/matrix-triangle-resolve-enum' );
var resolveDiagonal = require( '@stdlib/blas/base/diagonal-type-resolve-enum' );
var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var format = require( '@stdlib/string/format' );


// VARIABLES //

var NORMS = {
	'max': 77,
	'one': 49,
	'infinity': 73,
	'frobenius': 70
};


// MAIN //

/**
* Validates the norm, triangular storage, diagonal type, and dimensions.
*
* @private
* @param {string} norm - norm type
* @param {(string|integer)} uplo - triangle type
* @param {(string|integer)} diag - diagonal type
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @throws {TypeError} invalid norm, triangle, or diagonal type
* @throws {RangeError} invalid trapezoidal dimensions
* @returns {Array} normalized options
*/
function validate( norm, uplo, diag, M, N ) {
	var n;
	var u;
	var d;

	if ( typeof norm !== 'string' || !Object.prototype.hasOwnProperty.call( NORMS, norm ) ) {
		throw new TypeError( format( 'invalid argument. Norm must be "max", "one", "infinity", or "frobenius". Value: `%s`.', norm ) );
	}
	n = NORMS[ norm ];
	u = resolveTriangle( uplo );
	if ( u === null ) {
		throw new TypeError( format( 'invalid argument. Triangle must be "upper" or "lower". Value: `%s`.', uplo ) );
	}
	d = resolveDiagonal( diag );
	if ( d === null ) {
		throw new TypeError( format( 'invalid argument. Diagonal must be "unit" or "non-unit". Value: `%s`.', diag ) );
	}
	if ( !isNonNegativeInteger( M ) || !isNonNegativeInteger( N ) ) {
		throw new RangeError( 'invalid argument. Matrix dimensions must be nonnegative integers.' );
	}
	if ( ( u === 121 && M > N ) || ( u === 122 && N > M ) ) {
		throw new RangeError( 'invalid argument. Upper trapezoidal matrices require M <= N; lower trapezoidal matrices require N <= M.' );
	}
	return [ n, u, d ];
}


// EXPORTS //

module.exports = validate;
